<?php
// WhatsApp Profile Checker API — PHP + cURL example. Docs: https://docs.numberchecker.ai/whatsapp-bulk-number-checker-avatar
const BASE_URL="https://api.numberchecker.ai"; const TASK_TYPE="ws_avatar"; $key=getenv("NUMBERCHECKER_API_KEY"); if($key===false||$key==='')throw new RuntimeException("NUMBERCHECKER_API_KEY is required");
function postApi(string $url,array $fields,string $key):array { $ch=curl_init($url); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>["X-API-Key: $key"],CURLOPT_POSTFIELDS=>$fields]); $body=curl_exec($ch); $status=curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch); if($status!==200&&$status!==202)throw new Exception("HTTP $status"); return json_decode($body,true); }
$created=postApi(BASE_URL."/v1/tasks",["file"=>new CURLFile("examples/numbers.txt","text/plain","numbers.txt"),"task_type"=>TASK_TYPE],$key); $id=$created["task_id"]; echo "task_id: $id\n"; do { $task=postApi(BASE_URL."/v1/gettasks",["task_id"=>$id],$key); echo "status: {$task['status']}\n"; if($task["status"]==="failed")throw new Exception("task failed"); if($task["status"]!=="exported")sleep(5); } while($task["status"]!=="exported"); if(!empty($task["result_url"])){ $result=file_get_contents($task["result_url"]); if($result===false)throw new Exception("download failed"); file_put_contents("results.zip",$result); echo "saved to: results.zip\n"; }
